The same root problem can also cause issues with race conditions in tests, even when `inject` is not used. If `TestBed.createComponent` is used in an `async` test block, tasks spawned on that component will be tied to that first test block. That means that a later test block won't know about those actions, and could exit early. For example:

``` ts
    beforeEach(async(() => {
      TestBed.configureTestingModule({
        declarations: [AsyncInitTestApp],
      });

      TestBed.compileComponents().then(() => {
        fixture = TestBed.createComponent(AsyncInitTestApp);
      });
    }));

    it('should show tabs when they are available', async(() => {
      fixture.detectChanges();

      fixture.whenStable().then(() => {
        // The test won't properly wait for stability before continuing!!
      });
    }));
  });
```

(full example: https://gist.github.com/juliemr/d78fe8313bdb775acd7f4c944584ce67)

Rough proposal to create a special zone spec that knows how to proxy to delegate specs:

```
// @angular/core/testing
=========
let _testProxyZoneSpec = null;


// lots of hand-waving here.. actual implementation will likely be very different
function async(fn) {
  _testProxyZoneSpec.setDelegate(new AsyncTestSpec());
  ...
  fn();
  ...
  // wait until fn async stuff is done then:
  _testProxyZoneSpec.setDelegate(null);
}

// lots of hand-waving here.. actual implementation will likely be very different
function fakeAsync(fn) {
  _testProxyZoneSpec.setDelegate(new FakeAsyncTestSpec());
  ...
  fn();
  ...
  _testProxyZoneSpec.setDelegate(null);
}

beforeEach(() => {
  // Zone.current: root
  // ngZone: null
  _testProxyZoneSpec = new TestProxyZoneSpec();
  Zone.current.fork(_testProxyZoneSpec);
  // Zone.current: root -> testZone(spec redirecting to: null)
  // ngZone: null
})


// application spec
=======
beforeEach(inject(tcb: TestComponentBuilder) => {
  // Zone.current: root -> testZone(spec redirecting to: null)
  // ngZone: root -> testZone -> ngZone
})


it('should ...', async(() => {
  // Zone.current: root -> testZone(spec redirecting to: async)
  // ngZone: root -> testZone -> ngZone
  doAsyncWork();
}));


it('should ...', fakeAsync(() => {
  // Zone.current: root -> testZone(spec redirecting to: fakeAsync)
  // ngZone: root -> testZone -> ngZone
  doAsyncWork();
  flushMicrotasks();
}));
```
